static constexpr size_t kEntryCount = sizeof(kEntries) / sizeof(kEntries[0]);

inline const Entry *entryAt(size_t index) {
    return index < kEntryCount ? &kEntries[index] : nullptr;
}

inline bool modelMatches(const Entry &e, const char *model_id) {
    if (!model_id) return false;
    const char *a = e.model_id;
    const char *b = model_id;
    while (*a && *b && *a == *b) { ++a; ++b; }
    return *a == '\0' && *b == '\0';
}

inline size_t countForModel(const char *model_id) {
    size_t n = 0;
    for (size_t i = 0; i < kEntryCount; ++i)
        if (modelMatches(kEntries[i], model_id)) ++n;
    return n;
}

inline bool hasUsidForModel(const char *model_id, uint8_t usid) {
    for (size_t i = 0; i < kEntryCount; ++i)
        if (modelMatches(kEntries[i], model_id) && kEntries[i].usid == usid) return true;
    return false;
}

